import random

def get_user_choice():
    """Get user's choice as input."""
    choices = ["rock", "paper", "scissors"]
    while True:
        user_choice = input("Enter your choice (rock, paper, scissors): ").lower()
        if user_choice in choices:
            return user_choice
        else:
            print("Invalid input. Please enter a valid choice.")

def get_computer_choice():
    """Generate a random computer choice."""
    return random.choice(["rock", "paper", "scissors"])

def determine_winner(user_choice, computer_choice):
    """Determine the winner based on user and computer choices."""
    user_choices = {"rock": "scissors", "paper": "rock", "scissors": "paper"}
    return user_choices[user_choice] == computer_choice

def play_game():
    """Play a game of rock, paper, scissors with the user."""
    user_choice = get_user_choice()
    computer_choice = get_computer_choice()

    print(f"The computer chose {computer_choice.upper()}.")

    if determine_winner(user_choice, computer_choice):
        print("You win!")
    elif computer_choice == user_choice:
        print("It's a tie!")
    else:
        print("You lose!")

if __name__ == "__main__":
    play_game()
```
This program defines three functions: `get_user_choice()`, `get_computer_choice()`, and `determine_winner()`. The `play_game()` function calls these functions to get user input, generate a random computer choice, and determine the winner. The `if __name__ == "__main__":` guard ensures that the program only runs when it's being executed as the main script, not when it's being imported as a module.
